using System.Text;
using System.Text.Json;
using System.Text.RegularExpressions;
using ProjectBuilder.Core;

namespace ProjectBuilder.Generator;

/// <summary>
/// Generates the Angular web app: a fixed, readable template (login, list and form pages) plus
/// one generated file, <c>src/app/entities.ts</c>, describing the user's entities.
/// </summary>
internal static partial class WebAppGenerator
{
    private const string Prefix = "AngularTemplate/";
    private const string EntitiesPath = "src/app/entities.ts";

    public static IEnumerable<GeneratedFile> Generate(AppDefinition app)
    {
        var asm = typeof(WebAppGenerator).Assembly;
        var slug = Regex.Replace(app.Name.Trim().ToLowerInvariant(), "[^a-z0-9]+", "-").Trim('-');
        string entitiesTemplate = "";

        foreach (var resource in asm.GetManifestResourceNames().Select(n => (Raw: n, Name: n.Replace('\\', '/')))
                     .Where(n => n.Name.StartsWith(Prefix, StringComparison.Ordinal)).OrderBy(n => n.Name, StringComparer.Ordinal))
        {
            var path = resource.Name[Prefix.Length..];
            using var stream = asm.GetManifestResourceStream(resource.Raw)!;
            using var reader = new StreamReader(stream);
            var text = reader.ReadToEnd();

            if (path == EntitiesPath) { entitiesTemplate = text; continue; }
            yield return new GeneratedFile(path, text.Replace("__APP_NAME__", app.Name).Replace("__APP_SLUG__", slug));
        }

        yield return new GeneratedFile(EntitiesPath, EntitiesTs(app, entitiesTemplate));
    }

    private static string EntitiesTs(AppDefinition app, string template)
    {
        // Keep the type declarations from the template (everything before the APP_NAME constant).
        var marker = template.IndexOf("export const APP_NAME", StringComparison.Ordinal);
        var header = marker > 0 ? template[..marker] : "";
        header = header.Replace("// Placeholder so the template type-checks on its own; the generator replaces this file with your system's description.",
            "// Generated by ProjectBuilder from your system design. Regenerate rather than editing the data below.");

        var entities = app.Entities.Select(e => new
        {
            name = e.Name,
            label = Humanize(e.Name),
            plural = Humanize(Naming.Plural(e.Name)),
            route = Naming.Plural(e.Name).ToLowerInvariant(),
            display = DisplayField(e),
            fields = e.Fields.Select(f => new
            {
                key = OpenApiGenerator.CamelCase(f.Name),
                label = Humanize(f.Name),
                type = f.Type.ToString(),
                required = f.Required,
                maxLength = f.MaxLength is > 0 ? f.MaxLength : null
            }),
            relations = e.Relations.Select(r => new
            {
                key = OpenApiGenerator.CamelCase(r.Name) + "Id",
                label = Humanize(r.Name),
                target = r.TargetEntity,
                required = r.Required
            })
        });

        var options = new JsonSerializerOptions
        {
            WriteIndented = true,
            DefaultIgnoreCondition = System.Text.Json.Serialization.JsonIgnoreCondition.WhenWritingNull
        };
        // JSON string escaping also makes the values safe inside TypeScript.
        var sb = new StringBuilder(header);
        sb.AppendLine($"export const APP_NAME = {JsonSerializer.Serialize(app.Name)};");
        sb.AppendLine($"export const ENTITIES: EntityMeta[] = {JsonSerializer.Serialize(entities, options)};");
        return sb.ToString();
    }

    /// <summary>The field shown to people when a record is referenced (dropdowns, relation columns).</summary>
    private static string DisplayField(EntityDefinition e)
    {
        var textual = e.Fields.Where(f => f.Type is FieldType.String or FieldType.Text or FieldType.Email or FieldType.Phone).ToList();
        var pick = textual.FirstOrDefault(f => f.Required) ?? textual.FirstOrDefault() ?? e.Fields.FirstOrDefault();
        return pick is null ? "id" : OpenApiGenerator.CamelCase(pick.Name);
    }

    /// <summary>"DateOfBirth" -> "Date Of Birth".</summary>
    internal static string Humanize(string name) => HumanizeRegex().Replace(name, " ");

    [GeneratedRegex("(?<=[a-z0-9])(?=[A-Z])")]
    private static partial Regex HumanizeRegex();
}
